bool FURLabRpcDispatcher::DispatchTypedViewer(const FURLabRequestEnvelope&Request,const FURLabRequestDigest&Digest,const FURLabRequestLedger::FSessionRef&Session,const FURLabRenderOwnerSessionScopePtr&OwnerScope,const FURLabDataSessionPtr&DataSession,TArray<uint8>&Out){FURLabRequestLedger::FAdmissionResult A;bool Start=false;auto C=MakeShared<FURLabRetainedCompletion,ESPMode::ThreadSafe>(RequestLedger,Session,Request,Digest);{FScopeLock L(&DispatchMutex);auto B=ViewerService;auto Camera=CameraStreamService;A=RequestLedger->Admit(Session,Request.RequestId,Digest);if(A.Status==FURLabRequestLedger::Accepted){auto Store=PayloadStore;auto Bridge=OwningBridge;FURLabGameThreadCommandQueue::FWork W;W.Execute=[C,B,Camera,OwnerScope,DataSession,Store,Bridge](){Execute(C,B,Camera,OwnerScope,DataSession,Store,Bridge);};W.Cancel=[C](){C->Error(TEXT("service_unavailable"),TEXT("Viewer command cancelled"));};Start=RenderCommandQueue->Enqueue(MoveTemp(W));}}auto R=FURLabRetainedCompletion::EncodeAdmission(A,Request,Out);if(R!=EURLabRetainedAdmissionReply::Accepted)return R==EURLabRetainedAdmissionReply::Replied;if(IsInGameThread())RenderCommandQueue->Drain();else if(Start){auto Q=RenderCommandQueue;AsyncTask(ENamedThreads::GameThread,[Q](){Q->Drain();});}auto Done=RequestLedger->Admit(Session,Request.RequestId,Digest);if(Done.Terminal==FURLabRequestLedger::Completed&&Done.ReplyBytes){Out=*Done.ReplyBytes;return true;}FURLabRequestEnvelopeCodec::EncodeReply(FURLabReplyEnvelope::MakePending(Request),Out);return true;}
